//! Thin OAuth/HTTP shell. Request and response policy lives in calendar_wire.
use super::calendar_range::CalendarTimeRange;
use std::{collections::BTreeSet, path::PathBuf, sync::Arc, time::Duration};
use tokio::sync::{Mutex, Notify, OnceCell};
use yup_oauth2::{
    authenticator::DefaultAuthenticator, InstalledFlowAuthenticator, InstalledFlowReturnMethod,
};

use super::{
    calendar_client::{CalendarApi, CalendarApiFuture},
    calendar_projection::DesiredEvent,
    calendar_wire::{
        self as wire, Operation, ResponseAction, WireRequest, CALENDAR_API_BASE, CALENDAR_SCOPE,
    },
};
use crate::{api::planning::DiagnosticBody, config::ServerConfig};

pub struct GoogleCalendarApi {
    client: reqwest::Client,
    calendar_id: String,
    api_base: String,
    credentials_path: PathBuf,
    token_cache_path: PathBuf,
    authenticator: OnceCell<DefaultAuthenticator>,
    consent_failed: Arc<Notify>,
    diagnostics: Mutex<Vec<DiagnosticBody>>,
    /// Ids of listed events carrying UbU's own stamp, accumulated across pages and drained after a list.
    ubu_created_ids: Mutex<BTreeSet<String>>,
}

impl GoogleCalendarApi {
    /// Construction performs no OAuth or credential I/O. The apply gate must
    /// grant a permit before the first CalendarApi method is called.
    pub fn new(config: &ServerConfig) -> Result<Self, String> {
        let credentials_path = config
            .google_credentials_path()
            .ok_or("initialize event `*`: UBU_GOOGLE_CREDENTIALS_PATH is required")?
            .to_owned();
        let token_cache_path = config
            .google_token_cache_path()
            .ok_or("initialize event `*`: UBU_GOOGLE_TOKEN_CACHE_PATH is required")?
            .to_owned();
        let client = reqwest::Client::builder()
            .timeout(Duration::from_secs(30))
            .redirect(reqwest::redirect::Policy::none())
            .build()
            .map_err(|_| "initialize event `*`: could not initialize Calendar HTTP client")?;
        Ok(Self {
            client,
            calendar_id: config.google_calendar_id().into(),
            api_base: CALENDAR_API_BASE.into(),
            credentials_path,
            token_cache_path,
            authenticator: OnceCell::new(),
            consent_failed: Arc::new(Notify::new()),
            diagnostics: Mutex::new(Vec::new()),
            ubu_created_ids: Mutex::new(BTreeSet::new()),
        })
    }

    pub async fn take_diagnostics(&self) -> Vec<DiagnosticBody> {
        std::mem::take(&mut *self.diagnostics.lock().await)
    }

    async fn access_token(&self, request: &WireRequest) -> Result<String, String> {
        let fail =
            |reason: &str| wire::operation_error(request.operation, &request.event_id, reason);
        let auth = self
            .authenticator
            .get_or_try_init(|| async {
                let secret = yup_oauth2::read_application_secret(&self.credentials_path)
                    .await
                    .map_err(|_| "UBU_GOOGLE_CREDENTIALS_PATH is unreadable or invalid")?;
                InstalledFlowAuthenticator::builder(secret, InstalledFlowReturnMethod::HTTPRedirect)
                    .flow_delegate(Box::new(BrowserDelegate {
                        failed: self.consent_failed.clone(),
                    }))
                    .persist_tokens_to_disk(&self.token_cache_path)
                    .build()
                    .await
                    .map_err(|_| "UBU_GOOGLE_TOKEN_CACHE_PATH is unreadable or invalid")
            })
            .await
            .map_err(fail)?;
        // yup-oauth2 9's HTTPRedirect flow ignores delegate errors. Race an
        // explicit failure notification against it, so headless/missing-browser
        // consent fails immediately instead of waiting forever for a callback.
        let token = tokio::select! {
            biased;
            _ = self.consent_failed.notified() => return Err(fail("OAuth consent requires a working desktop browser; no prompt was opened")),
            result = tokio::time::timeout(Duration::from_secs(300), auth.token(&[CALENDAR_SCOPE])) => {
                result.map_err(|_| fail("OAuth consent or token refresh timed out"))?
                    .map_err(|_| fail("OAuth failed; check UBU_GOOGLE_CREDENTIALS_PATH and writable UBU_GOOGLE_TOKEN_CACHE_PATH"))?
            }
        };
        token
            .token()
            .map(str::to_owned)
            .ok_or_else(|| fail("OAuth returned no access token"))
    }

    async fn send(&self, request: &WireRequest) -> Result<(u16, String), String> {
        let token = self.access_token(request).await?;
        let fail =
            |reason: &str| wire::operation_error(request.operation, &request.event_id, reason);
        let method = reqwest::Method::from_bytes(request.operation.method().as_bytes())
            .map_err(|_| fail("invalid HTTP method"))?;
        let mut builder = self.client.request(method, &request.url);
        for (name, value) in request.headers(&token) {
            builder = builder.header(name, value);
        }
        if let Some(body) = &request.body {
            builder = builder.json(body);
        }
        let response = builder
            .send()
            .await
            .map_err(|_| fail("Calendar HTTP request failed"))?;
        let status = response.status().as_u16();
        let body = response
            .text()
            .await
            .map_err(|_| fail("Calendar HTTP response could not be read"))?;
        Ok((status, body))
    }

    async fn write(
        &self,
        mut request: WireRequest,
        event: Option<&DesiredEvent>,
    ) -> Result<(), String> {
        loop {
            let (status, body) = self.send(&request).await?;
            match wire::response_action(request.operation, &request.event_id, status, &body) {
                ResponseAction::Done => return Ok(()),
                ResponseAction::Failed(message) => return Err(message),
                ResponseAction::Patch => {
                    self.diagnostics.lock().await.push(DiagnosticBody {
                        code: "calendar_insert_converted_to_patch".into(),
                        message: wire::operation_error(
                            Operation::Insert,
                            &request.event_id,
                            "HTTP 409; converting insert to patch",
                        ),
                    });
                    let event = event.ok_or_else(|| {
                        wire::operation_error(
                            Operation::Insert,
                            &request.event_id,
                            "missing event for patch",
                        )
                    })?;
                    request = wire::event_request(
                        Operation::Patch,
                        &self.api_base,
                        &self.calendar_id,
                        event,
                    );
                }
            }
        }
    }
}

impl CalendarApi for GoogleCalendarApi {
    fn take_diagnostics(&self) -> super::calendar_client::CalendarDiagnosticsFuture<'_> {
        Box::pin(GoogleCalendarApi::take_diagnostics(self))
    }
    fn take_ubu_created_ids(&self) -> super::calendar_client::CalendarCreatedIdsFuture<'_> {
        Box::pin(async move { std::mem::take(&mut *self.ubu_created_ids.lock().await) })
    }
    fn list_events<'a>(&'a self, range: &'a CalendarTimeRange) -> CalendarApiFuture<'a, Vec<DesiredEvent>> {
        Box::pin(async move {
            let mut events = Vec::new();
            let mut page = None;
            let mut seen = BTreeSet::new();
            loop {
                let request =
                    wire::list_request(&self.api_base, &self.calendar_id, range, page.as_deref());
                let (status, body) = self.send(&request).await?;
                match wire::response_action(Operation::List, "*", status, &body) {
                    ResponseAction::Done => {}
                    ResponseAction::Failed(message) => return Err(message),
                    ResponseAction::Patch => {
                        unreachable!("wire policy only patches conflicting inserts")
                    }
                }
                let value = serde_json::from_str(&body)
                    .map_err(|_| "list event `*`: invalid Google Calendar JSON")?;
                let (parsed, skipped) = wire::parse_event_list(&value);
                events.extend(parsed);
                self.diagnostics
                    .lock()
                    .await
                    .extend(skipped.into_iter().map(wire::list_diagnostic));
                self.ubu_created_ids
                    .lock()
                    .await
                    .extend(wire::ubu_created_ids(&value));
                page = wire::next_page(&value, &mut seen)?;
                if page.is_none() {
                    return Ok(events);
                }
            }
        })
    }

    fn insert_event<'a>(&'a self, event: &'a DesiredEvent) -> CalendarApiFuture<'a, ()> {
        Box::pin(self.write(
            wire::event_request(Operation::Insert, &self.api_base, &self.calendar_id, event),
            Some(event),
        ))
    }

    fn patch_event<'a>(&'a self, event: &'a DesiredEvent) -> CalendarApiFuture<'a, ()> {
        Box::pin(self.write(
            wire::event_request(Operation::Patch, &self.api_base, &self.calendar_id, event),
            Some(event),
        ))
    }

    fn delete_event<'a>(&'a self, external_id: &'a str) -> CalendarApiFuture<'a, ()> {
        Box::pin(self.write(
            wire::delete_request(&self.api_base, &self.calendar_id, external_id),
            None,
        ))
    }
}

struct BrowserDelegate {
    failed: Arc<Notify>,
}
impl yup_oauth2::authenticator_delegate::InstalledFlowDelegate for BrowserDelegate {
    fn present_user_url<'a>(
        &'a self,
        url: &'a str,
        need_code: bool,
    ) -> CalendarApiFuture<'a, String> {
        Box::pin(async move {
            let desktop = cfg!(target_os = "macos")
                || cfg!(target_os = "windows")
                || std::env::var_os("DISPLAY").is_some_and(|value| !value.is_empty())
                || std::env::var_os("WAYLAND_DISPLAY").is_some_and(|value| !value.is_empty());
            if need_code || !desktop {
                self.failed.notify_one();
                return Err("interactive consent unavailable".into());
            }
            let url = url.to_owned();
            let opened = tokio::task::spawn_blocking(move || {
                use std::process::{Command, Stdio};
                #[cfg(target_os = "macos")]
                let mut command = Command::new("open");
                #[cfg(target_os = "windows")]
                let mut command = {
                    let mut c = Command::new("rundll32.exe");
                    c.arg("url.dll,FileProtocolHandler");
                    c
                };
                #[cfg(not(any(target_os = "macos", target_os = "windows")))]
                let mut command = Command::new("xdg-open");
                command
                    .arg(url)
                    .stdin(Stdio::null())
                    .stdout(Stdio::null())
                    .stderr(Stdio::null())
                    .status()
                    .is_ok_and(|status| status.success())
            })
            .await
            .unwrap_or(false);
            if opened {
                Ok(String::new())
            } else {
                self.failed.notify_one();
                Err("browser could not be opened".into())
            }
        })
    }
}
//! Pure Google Calendar request, response and status policy. No transport types.
use serde::Serialize;
use serde_json::Value;
use std::collections::BTreeSet;

use super::calendar_projection::DesiredEvent;

pub const CALENDAR_SCOPE: &str = "https://www.googleapis.com/auth/calendar";
pub const CALENDAR_API_BASE: &str = "https://www.googleapis.com/calendar/v3/calendars";
/// The private extended property UbU writes on an event it creates.
pub const UBU_TASK_PROPERTY: &str = "ubu_task";

// Field order and omission rules match quick-ubu/gcal's GoogleEventBody.
#[derive(Debug, Serialize)]
pub struct GoogleEventBody {
    pub summary: String,
    pub start: GoogleEventTime,
    pub end: GoogleEventTime,
    #[serde(rename = "colorId", skip_serializing_if = "Option::is_none")]
    pub color_id: Option<String>,
    pub transparency: String,
    pub reminders: GoogleReminders,
}

#[derive(Debug, Serialize)]
pub struct GoogleReminders {
    #[serde(rename = "useDefault")]
    pub use_default: bool,
    pub overrides: Vec<GoogleReminder>,
}

#[derive(Debug, Serialize)]
pub struct GoogleReminder {
    pub method: &'static str,
    // DesiredEvent uses i64; preserve it without narrowing or truncation.
    pub minutes: i64,
}

#[derive(Debug, Serialize)]
pub struct GoogleEventTime {
    #[serde(rename = "dateTime")]
    pub date_time: String,
}

pub fn event_body(event: &DesiredEvent) -> GoogleEventBody {
    GoogleEventBody {
        summary: event.summary.clone(),
        start: GoogleEventTime {
            date_time: event.start_at.clone(),
        },
        end: GoogleEventTime {
            date_time: event.end_at.clone(),
        },
        color_id: event.color_id.clone(),
        transparency: if event.transparent {
            "transparent"
        } else {
            "opaque"
        }
        .into(),
        reminders: GoogleReminders {
            use_default: false,
            overrides: event
                .reminders_minutes
                .iter()
                .map(|&minutes| GoogleReminder {
                    method: "popup",
                    minutes,
                })
                .collect(),
        },
    }
}

fn required_string<'a>(value: &'a Value, field: &str) -> Result<&'a str, String> {
    value
        .get(field)
        .and_then(Value::as_str)
        .ok_or_else(|| format!("missing or invalid {field}"))
}

/// An all-day event has a date and no time, so it has no length. It cannot be a
/// Dynamic Task without inventing a duration, and a commitment with no time has
/// no window to pin. It is skipped, and the message says why.
pub const ALL_DAY_MESSAGE: &str = "all-day event has no dateTime; it carries no duration, so it cannot be scheduled and is skipped";

pub fn parse_event(value: &Value) -> Result<DesiredEvent, String> {
    parse_event_with_diagnostic(value).map(|(event, _)| event)
}

pub const DESCRIPTION_TOO_LARGE_CODE: &str = "capture_description_too_large";

fn description_limit_message() -> String {
    format!("description exceeds {} bytes; notes were not imported, but the event remains available for capture", super::clarify::MAX_DESCRIPTION_BYTES)
}

/// The same policy for Google input, normalized mock input and capture planning.
/// Whitespace is trimmed; markup and interior text are otherwise untouched.
pub fn capture_description(id: &str, raw: Option<&str>) -> (Option<String>, Option<String>) {
    let Some(text) = raw.map(str::trim).filter(|text| !text.is_empty()) else {
        return (None, None);
    };
    if text.len() > super::clarify::MAX_DESCRIPTION_BYTES {
        return (None, Some(format!("Calendar event `{id}`: {}", description_limit_message())));
    }
    (Some(text.to_owned()), None)
}

pub fn parse_event_with_diagnostic(value: &Value) -> Result<(DesiredEvent, Option<String>), String> {
    if value.get("status").and_then(Value::as_str) == Some("cancelled") {
        return Err("cancelled event".into());
    }
    let id = required_string(value, "id")?;
    let task_id = format!("task_{id}");
    let summary = required_string(value, "summary")?;
    let raw_description = match value.get("description") {
        None => None,
        Some(Value::String(text)) => Some(text.as_str()),
        _ => return Err("invalid description".into()),
    };
    let (description, description_diagnostic) = capture_description(id, raw_description);
    if value["start"].get("date").is_some() && value["start"].get("dateTime").is_none() {
        return Err(ALL_DAY_MESSAGE.into());
    }
    let start_at = required_string(&value["start"], "dateTime")?;
    let end_at = required_string(&value["end"], "dateTime")?;
    let start =
        chrono::DateTime::parse_from_rfc3339(start_at).map_err(|_| "invalid start.dateTime")?;
    let end = chrono::DateTime::parse_from_rfc3339(end_at).map_err(|_| "invalid end.dateTime")?;
    if end <= start {
        return Err("end.dateTime must follow start.dateTime".into());
    }
    let color_id = match value.get("colorId") {
        None => None,
        Some(Value::String(color)) => Some(color.clone()),
        _ => return Err("invalid colorId".into()),
    };
    // Like Quick UbU, an absent transparency means opaque.
    let transparent = match value.get("transparency") {
        None => false,
        Some(Value::String(transparency)) => transparency == "transparent",
        _ => return Err("invalid transparency".into()),
    };
    let reminders = &value["reminders"];
    // Default reminders are Calendar settings, not Task metadata. No explicit
    // reminder can be recovered from an omitted/default reminder specification.
    let explicit = match reminders.get("useDefault") {
        Some(Value::Bool(false)) => reminders.get("overrides"),
        Some(Value::Bool(true)) => None,
        None if reminders.is_null() => None,
        _ => return Err("invalid reminders.useDefault".into()),
    };
    let overrides = match explicit {
        None => &[][..], // Google may omit an empty overrides array.
        Some(Value::Array(overrides)) => overrides.as_slice(),
        _ => return Err("invalid reminders.overrides".into()),
    };
    let reminders_minutes = overrides
        .iter()
        .map(|reminder| {
            if reminder["method"] != "popup" {
                return Err("unsupported reminder method".into());
            }
            reminder["minutes"]
                .as_i64()
                .filter(|minutes| *minutes >= 0)
                .ok_or_else(|| "invalid reminder minutes".into())
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok((DesiredEvent {
        external_id: id.into(),
        task_id,
        summary: summary.into(),
        description,
        start_at: start_at.into(),
        end_at: end_at.into(),
        color_id,
        transparent,
        reminders_minutes,
    }, description_diagnostic))
}

pub fn parse_event_list(value: &Value) -> (Vec<DesiredEvent>, Vec<String>) {
    let Some(items) = value.get("items").and_then(Value::as_array) else {
        return (
            Vec::new(),
            vec!["list event `*`: missing or invalid items".into()],
        );
    };
    let mut events = Vec::new();
    let mut messages = Vec::new();
    for (index, item) in items.iter().enumerate() {
        match parse_event_with_diagnostic(item) {
            Ok((event, diagnostic)) => {
                events.push(event);
                messages.extend(diagnostic);
            }
            // Identify the entry by index and readable handle, never by its title or content.
            Err(message) => {
                let id = item.get("id").and_then(Value::as_str).unwrap_or("*");
                messages.push(format!("list event `{id}` entry {index}: {message}"));
            }
        }
    }
    (events, messages)
}

/// Ids of listed events UbU minted itself: the stamp is present and names the Task
/// whose handle the event id is. An event UbU only patched carries no stamp, and a
/// stamp that does not match the id is not evidence of minting.
///
/// Every absence yields fewer ids and never a failure: no `items`, no
/// `extendedProperties`, a `private` that is not an object, a stamp that is not a
/// string. `parse_event_list` reads the same JSON for the events themselves; this is
/// a second pass over it for where they came from.
pub fn ubu_created_ids(value: &Value) -> BTreeSet<String> {
    value
        .get("items")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|item| {
            let id = item.get("id")?.as_str()?;
            let stamp = item
                .get("extendedProperties")?
                .get("private")?
                .get(UBU_TASK_PROPERTY)?
                .as_str()?;
            (stamp == format!("task_{id}")).then(|| id.to_owned())
        })
        .collect()
}

pub fn list_diagnostic(message: String) -> crate::api::planning::DiagnosticBody {
    crate::api::planning::DiagnosticBody {
        code: if message.ends_with(ALL_DAY_MESSAGE) { "capture_all_day_unsupported" } else if message.ends_with(&description_limit_message()) { DESCRIPTION_TOO_LARGE_CODE } else { "calendar_event_skipped" }.into(),
        message,
    }
}

fn percent_encode(value: &str) -> String {
    let mut encoded = String::new();
    for byte in value.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
            encoded.push(char::from(byte));
        } else {
            use std::fmt::Write;
            write!(encoded, "%{byte:02X}").expect("writing to a String cannot fail");
        }
    }
    encoded
}

pub fn events_url(base: &str, calendar_id: &str, event_id: Option<&str>) -> String {
    let mut url = format!(
        "{}/{}/events",
        base.trim_end_matches('/'),
        percent_encode(calendar_id)
    );
    if let Some(id) = event_id {
        url.push('/');
        url.push_str(&percent_encode(id));
    }
    url
}

#[derive(Debug, PartialEq, Eq)]
pub enum WireOutcome {
    Ok,
    AlreadyGone,
    Conflict,
    Failed(String),
}

pub fn outcome_for(status: u16, body: &str) -> WireOutcome {
    match status {
        200..=299 => WireOutcome::Ok,
        404 | 410 => WireOutcome::AlreadyGone,
        409 => WireOutcome::Conflict,
        _ => WireOutcome::Failed(body.into()),
    }
}

