//! Offline Calendar client boundary. No provider types or transport live here.
use super::calendar_range::CalendarTimeRange;
use std::{
    collections::{BTreeMap, BTreeSet},
    future::Future,
    pin::Pin,
    sync::Mutex,
};

use serde::{Deserialize, Serialize};
